-- Demo seed: Advanced Description for two of seven blog articles (~29%,
-- the nearest whole-article match to 25%). Post 1 keeps the composition
-- converted from its former Builder page; post 3 adds a lightweight
-- six-section article description using the shared section registry.
--
-- Both halves are generated through Dockercart\Description\Sections
-- (normalizeDocument + editorDocument) and filled for all three panel
-- languages. Classic WYSIWYG content remains untouched for search/snippets
-- and as the fallback. Idempotent: non-empty compositions are never replaced.

UPDATE `oc_blog_post` SET `use_advanced_description` = 1, `advanced_description` = '{"sections":[{"sid":"s1","type":"text","settings":{"align":"center"}},{"sid":"s2","type":"features","settings":{"columns":"3"},"rows":[{"icon":"headphones"},{"icon":"volume-2"},{"icon":"shield-check"}]},{"sid":"s3","type":"text_image","settings":{"image":"blog/post-3-headphones.jpg","position":"left"}},{"sid":"s4","type":"stats","settings":{"columns":"3"},"rows":[[],[],[]]},{"sid":"s5","type":"gallery","settings":{"columns":"3"},"rows":[{"image":"blog/post-3-headphones.jpg"},{"image":"blog/post-1-smartphones.jpg"},{"image":"blog/post-2-laptops.jpg"}]},{"sid":"s6","type":"statement","settings":[]}]}'
	WHERE `post_id` = 3 AND (`advanced_description` IS NULL OR `advanced_description` = '');

UPDATE `oc_blog_post_description` SET `advanced_content` = '{"s1":{"heading":"Choose with confidence","body":"<p>Good headphones make every day better. This guide collects the details that matter before you buy: fit, sound, comfort and how you plan to use them.</p>"},"s2":{"heading":"What to compare","rows":[{"title":"Comfort","text":"Over-ear models are relaxed at home; in-ear models travel easily."},{"title":"Sound","text":"Look for a balanced range and clean mids, not only deep bass."},{"title":"Daily use","text":"Battery life, controls and folding design matter more than looks."}]},"s3":{"heading":"Fit for your routine","body":"<p>Try a few shapes and sizes. A secure, comfortable fit changes how music feels during work, sport or a long journey.</p>"},"s4":{"rows":[{"value":"20-20k","label":"Hz frequency range"},{"value":"40h","label":"typical battery life"},{"value":"3","label":"popular form factors"}]},"s5":{"rows":[{"caption":"Over-ear"},{"caption":"In-ear"},{"caption":"Sport"}]},"s6":{"text":"The best headphones are the ones you forget you are wearing.","footnote":"DockerCart editorial team"}}'
	WHERE `post_id` = 3 AND `language_id` = 1 AND (`advanced_content` IS NULL OR `advanced_content` = '');

UPDATE `oc_blog_post_description` SET `advanced_content` = '{"s1":{"heading":"Обирайте впевнено","body":"<p>Хороші навушники роблять кожен день кращим. У цьому посібнику зібрані деталі, які справді важливі перед покупкою: посадка, звук, комфорт і спосіб використання.</p>"},"s2":{"heading":"Що порівнювати","rows":[{"title":"Комфорт","text":"Повнорозмірні моделі зручні вдома, а внутрішньоканальні легко брати з собою."},{"title":"Звук","text":"Звертайте увагу на збалансований діапазон і чисті середини, а не лише на глибокий бас."},{"title":"Щоденне використання","text":"Важливіші час роботи, керування та можливість складатися, ніж лише вигляд."}]},"s3":{"heading":"Під ваш ритм","body":"<p>Спробуйте кілька форм і розмірів. Надійна та комфортна посадка змінює враження від музики під час роботи, спорту чи довгої подорожі.</p>"},"s4":{"rows":[{"value":"20-20 кГц","label":"частотний діапазон"},{"value":"40 год","label":"типова робота від акумулятора"},{"value":"3","label":"популярні типи"}]},"s5":{"rows":[{"caption":"Повнорозмірні"},{"caption":"Внутрішньоканальні"},{"caption":"Спортивні"}]},"s6":{"text":"Найкращі навушники — ті, про які ви забуваєте.","footnote":"Редакція DockerCart"}}'
	WHERE `post_id` = 3 AND `language_id` = 2 AND (`advanced_content` IS NULL OR `advanced_content` = '');

UPDATE `oc_blog_post_description` SET `advanced_content` = '{"s1":{"heading":"Выбирайте уверенно","body":"<p>Хорошие наушники делают каждый день лучше. В этом руководстве собраны детали, которые действительно важны перед покупкой: посадка, звук, комфорт и способ использования.</p>"},"s2":{"heading":"Что сравнивать","rows":[{"title":"Комфорт","text":"Полноразмерные модели хороши дома, а внутриканальные легко брать с собой."},{"title":"Звук","text":"Смотрите на сбалансированный диапазон и чистые середины, а не только на глубокий бас."},{"title":"Повседневное использование","text":"Важнее время работы, управление и возможность складываться, чем только внешний вид."}]},"s3":{"heading":"Под ваш ритм","body":"<p>Попробуйте несколько форм и размеров. Надёжная и комфортная посадка меняет впечатление от музыки во время работы, спорта или долгой поездки.</p>"},"s4":{"rows":[{"value":"20-20 кГц","label":"частотный диапазон"},{"value":"40 ч","label":"типичная работа от аккумулятора"},{"value":"3","label":"популярные типы"}]},"s5":{"rows":[{"caption":"Полноразмерные"},{"caption":"Внутриканальные"},{"caption":"Спортивные"}]},"s6":{"text":"Лучшие наушники — те, о которых вы забываете.","footnote":"Редакция DockerCart"}}'
	WHERE `post_id` = 3 AND `language_id` = 3 AND (`advanced_content` IS NULL OR `advanced_content` = '');
